uniform float uTime;
uniform float uFrame;
uniform float uFps;
uniform float uRms;

// Audio uniforms
uniform float audioLow;      // bass
uniform float audioLowSmooth; // bass_att
uniform float audioMid;      // mid
uniform float audioMidSmooth; // mid_att
uniform float audioHigh;     // treb
uniform float audioHighSmooth; // treb_att

// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;

// Input from vertex shader
in vec2 vUv;
in vec2 vUvOriginal;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;

// Helper functions
float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

// Texture helper functions
vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }

mat2 rot(float a)
void mirror(inout vec3 p, vec3 n)
float scene(vec3 p)
vec3 march(vec3 ro, vec3 rd)
vec3 getNormal(vec3 p)
vec3 getColor(vec3 p)

void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  // Original shader from laralubsch
// https://www.shadertoy.com/view/ltXyRS
// Constants
#define PI 3.14159265359
#define MaxSteps 64 // Steps (S)
#define Precision 0.004 // Precision (P)
#define MaxDist 2.0 // Max distance(D)
#define Iterations 20.0 // Iterations for scene function
// Global variables
static vec3 _ro; // Ray origin
static vec3 _rd; // Ray direction
static vec3 _p;  // Transformed position
static float _d;   // Distance to object
static float _t;   // Distance travelled
static float _s;   // Steps taken
// Helper functions
{
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}
{
    p -= 2.0 * n * min(0.0, dot(p, n));
}
{
    float a = uTime;
    float s = 1.5;
    p.xz = multiply(p.xz, rot(a));
    for (float i = 0.0; i < Iterations; i++)
    {
        a = (uTime / uTexSize.xy +mouse.x).x;
        p.xz = multiply(p.xz, rot(a+mouse.z));
        a = (uTime / uTexSize.xy +mouse.y).y;
        p.xy = multiply(p.xy, rot(a));
        mirror(p, normalize(vec3(0.0, 1.0, 1.0)));
        mirror(p, normalize(vec3(1.0, 0.0, 1.0)));
        mirror(p, normalize(vec3(1.0, 1.0, 0.0)));
        p = p * s - (s - 1.0) / 2.0;
    }
    _p = p;
    _d = length(p) / pow(s, Iterations);
    return _d;
}
{
    float t = Precision;
    vec3 p;
    int j;
    for (j = 0; j < MaxSteps; j++)
    {
        p = ro + rd * t;
        float d = scene(p);
        t += d;
        if (d < Precision || t > MaxDist)
        {
            _t = t;
            _s = float(j);
            j = MaxSteps;
        }
    }
    return vec3(p.x, p.y, p.z);
}
{
    vec2 e = vec2(Precision, 0.0);
    return normalize(vec3(
        scene(p + e.xyy) - scene(p - e.xyy),
        scene(p + e.yxy) - scene(p - e.yxy),
        scene(p + e.yyx) - scene(p - e.yyx)
    ));
}
{
    vec3 col = vec3(0.0, 0.0, 0.0);
    if (_d <= Precision || _t >= 2.0)
    {
        vec3 c = _p / length(_p);
        vec3 n = getNormal(p);
        vec3 l = _ro;
        float diff = max(dot(normalize(l - p), n), 0.0);
        float spec = pow(max(dot(reflect(normalize(p - l), n), normalize(_ro - p)), 0.0), 10.0);
        float aoc = _t < 2.0 ? 5.0 / _s : _s / float(MaxSteps);
        col = c * aoc + spec * step(_t, 2.0);
    }
    return col;
}
// UV setup
    vec2 xy = uv_orig;
    uv = (2.0 * xy - 1.0) * vec2(uTexSize.x / uTexSize.y, 1.0);

    // Camera setup
    _ro = vec3(uv.x, uv.y, -1.0);
    _rd = vec3(0.0, 0.0, 1.0);

    // Scene rendering
    vec3 col = getColor(march(_ro, _rd));

    ret = vec4(col, 1.0);
  fragColor = ret;
